# Verify my output pattern once more
even_row = [8, 8, 4, 8, 7, 8, 8, 8, 4, 8, 7, 4, 8, 8, 4, 8]  # rows 0,2,4,6,8,10
odd_row = [8, 7, 8, 8, 8, 4, 8, 7, 4, 8, 8, 4, 8, 7, 8, 8]  # rows 1,3,5,7,9

# Verify against input non-mask positions
import json
with open('/workspace/task/d791ad86/input.json') as f:
    input_data = json.load(f)
input_grid = [list(row.split()) for row in input_data['input'].splitlines()]

# Convert to int
input_grid = [[int(x) for x in row] for row in input_grid]

print("Verifying even rows (0,2,4,6,8,10) against input:")
for c in range(16):
    for r in [0,2,4,6,8,10]:
        if input_grid[r][c] != 5 and input_grid[r][c] != 8:
            expected = even_row[c]
            actual = input_grid[r][c]
            if expected != actual:
                print(f"  Mismatch at ({r},{c}): expected {expected}, got {actual}")

print("Verifying odd rows (1,3,5,7,9) against input:")
for c in range(16):
    for r in [1,3,5,7,9]:
        if input_grid[r][c] != 5 and input_grid[r][c] != 8:
            expected = odd_row[c]
            actual = input_grid[r][c]
            if expected != actual:
                print(f"  Mismatch at ({r},{c}): expected {expected}, got {actual}")

print("If all good, the pattern matches!")

# Submit again
print("\nFinal output grid:")
output = []
for r in range(11):
    if r % 2 == 0:
        output.append(even_row)
    else:
        output.append(odd_row)

print(json.dumps({"action": "submit", "grid": output}))

